// switchMap: cancel previous search request on new keystroke
searchControl.valueChanges.pipe(
  debounceTime(300),
  distinctUntilChanged(),
  switchMap(term => this.search.query(term).pipe(
    catchError(() => of([]))   // don't break the stream on error
  ))
).subscribe(results => this.results.set(results));

// exhaustMap: ignore button clicks while login is in progress
fromEvent(loginBtn, 'click').pipe(
  exhaustMap(() => this.auth.login(this.form.value))
).subscribe(user => this.router.navigate(['/dashboard']));

// concatMap: process items sequentially (order preserved)
from(fileList).pipe(
  concatMap(file => this.upload.send(file))
).subscribe(result => console.log('uploaded:', result.name));

// forkJoin: parallel HTTP calls — wait for all to complete
forkJoin({
  user: this.http.get<User>('/api/user'),
  perms: this.http.get<Permission[]>('/api/permissions'),
  config: this.http.get<Config>('/api/config')
}).subscribe(({ user, perms, config }) => {
  this.store.init(user, perms, config);
});

// combineLatest: react to ANY filter change
combineLatest([this.dateRange$, this.status$, this.searchTerm$]).pipe(
  debounceTime(100),          // debounce rapid multi-filter changes
  switchMap(([range, status, term]) => this.api.search({ range, status, term }))
).subscribe(data => this.data.set(data));

// shareReplay: share one HTTP call between multiple subscribers
readonly user$ = this.http.get<User>('/api/me').pipe(
  shareReplay(1)   // cache and replay to late subscribers — only one HTTP call
);

// catchError with retry and backoff
this.http.get('/api/data').pipe(
  retry({ count: 3, delay: (err, i) => timer(i * 1000) }),   // 1s, 2s, 3s backoff
  catchError(err => { console.error(err); return of(null); })
).subscribe(data => this.data.set(data));
